<?php
/** Proof — payment runs (spec "Proof", 4): due_by selects the approved bills; one payment per vendor; cheque numbers from the first typed at approval; the guards; record on the pay date; the CSV; void, "partly recorded". */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ap_fixture();
$R1 = mk_vendor('SMOKE Run Vendor One', ['pay_method' => 'cheque']); $R2 = mk_vendor('SMOKE Run Vendor Two', ['pay_method' => 'cheque']); $R3 = mk_vendor('SMOKE Run Vendor Three', ['pay_method' => 'ach']);
clear_open_bills([]);
$A = ready_bill($R1, [['Bill A', '1', '100.00']], ['vendor_ref' => 'A-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-01']);
$B = ready_bill($R2, [['Bill B', '1', '200.00']], ['vendor_ref' => 'B-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-05']);
$C = ready_bill($R3, [['Bill C', '1', '300.00']], ['vendor_ref' => 'C-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-10']);
$D = ready_bill($R1, [['Bill D, later', '1', '50.00']], ['vendor_ref' => 'D-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-08-01']);
$E = ready_bill($R2, [['Bill E, already in a payment', '1', '25.00']], ['vendor_ref' => 'E-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-02']);
$hold = mk_payment($R2, $fx['bank'], [$E]);
echo "1. Choosing the bills\n";
$body = page($bea, '/payment-runs/new?bank_account=' . $fx['bank'] . '&due_by=2026-07-15')['body'];
ok(str_contains($body, 'id="run-bill-' . $A . '"') && str_contains($body, 'id="run-bill-' . $B . '"') && str_contains($body, 'id="run-bill-' . $C . '"') && !str_contains($body, 'id="run-bill-' . $D . '"') && !str_contains($body, 'id="run-bill-' . $E . '"'), 'due by 15 Jul: A, B and C (not D due in August, not E already held by a draft payment)');
ok(str_contains($body, 'id="run-bills-total-amount"') && str_contains($body, 'class="form-check-input mt-0 run-bill"') && str_contains($body, 'Run Vendor One'), 'checkboxes grouped by vendor with a live total');
[$c, $d] = screen($bea, '/payment-runs/new?bank_account=' . $fx['bank'] . '&due_by=2026-07-15');
ok($c === 200 && count($d['bills'] ?? []) === 3 && ($d['bank_account']['currency'] ?? '') === 'USD', 'JSON: the three bills and the bank account');
echo "2. Create\n";
[$c, $b] = act($bea, '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-02', 'due_by' => '1999-01-01']);
ok($c === 422 && str_contains(msg($b), 'No approved bill is waiting to be paid by that date'), 'nothing due by then: 422 in words');
[$c, $b] = act($bea, '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-02']);
ok($c === 422 && isset(fields($b)['bills']), 'neither bills nor a due-by date: 422 naming bills');
[$c, $b] = act($bea, '/payment-runs/save.php', ['bank_account' => $fx['eur'], 'pay_date' => '2026-07-02', 'bills' => [$A]]);
ok($c === 422 && str_contains(msg($b), 'is in USD and SMOKE Euro account holds EUR'), 'a Euro bank for a dollar bill: 422 (' . msg($b) . ')');
$since = last_activity_id();
[$c, $b] = act($bea, '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-02', 'memo' => 'SMOKE July run', 'due_by' => '2026-07-15']);
$run = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $run > 0 && ($b['location'] ?? '') === '/payment-runs/' . $run . '?notice=saved' && count($b['payments'] ?? []) === 3, "payment_run_create by due_by: 200, record_id $run, three payments answered");
$r = run_row($run);
ok(preg_match('/^RUN-\d{5}$/', $r['number']) === 1 && $r['status'] === 'draft' && $r['total'] === '600.00' && $r['currency'] === 'USD' && $r['pay_date'] === '2026-07-02' && (int) $r['bank_account_id'] === $fx['bank'], 'a draft run RUN-…: 600.00 (the trigger\'s total), USD, pay date 2 Jul');
$ps = q('SELECT p.*, v.name FROM payments p JOIN vendors v ON v.id = p.vendor_id WHERE p.payment_run_id = :r ORDER BY p.id', ['r' => $run]);
ok(count($ps) === 3 && array_column($ps, 'method') === ['cheque', 'cheque', 'ach'] && array_column($ps, 'amount') === ['100.00', '200.00', '300.00'] && array_unique(array_column($ps, 'status')) === ['draft'] && array_column($ps, 'cheque_number') === [null, null, null], 'one draft payment per vendor, each with the vendor\'s method (cheque, cheque, ach), cheque numbers blank');
ok((int) one('SELECT count(*) FROM payment_applications pa JOIN payments p ON p.id = pa.payment_id WHERE p.payment_run_id = :r', ['r' => $run]) === 3, 'each applied to that vendor\'s bill');
$l = activity('payment_run.create', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['bank_account_id'] === $fx['bank'] && $a['amount'] === '600.00' && $a['payments'] === 3 && $a['bills'] === 3 && $a['currency'] === 'USD' && $a['number'] === $r['number'], 'payment_run.create logs bank_account_id, amount, payments, bills, currency');
ok((int) one("SELECT count(*) FROM notifications WHERE kind = 'payment_run_awaiting' AND record_type = 'payment_run' AND record_id = :r", ['r' => $run]) >= 1, 'the approvers are told (payment_run_awaiting)');
$body = page($bea, '/payment-runs/' . $run)['body'];
ok(str_contains($body, 'id="run-payments"') && str_contains($body, 'id="payment-run-add-form"') && str_contains($body, 'Run Vendor One') && !str_contains($body, 'id="payment-run-approve-btn"') && str_contains($body, 'id="payment-run-awaiting-note"'), 'the run page: its payments, the add form; a Bookkeeper sees "awaiting approval", not Approve');
echo "3. Add and remove while a draft\n";
$other = mk_payment($R1, $fx['cash'], [$D]);
[$c, $b] = act($bea, '/payment-runs/add.php', ['payment_run' => $run, 'payment' => $other]);
ok($c === 422 && str_contains(msg($b), 'is from another bank account or currency than run ' . $r['number']), 'a draft payment of another bank account: 422 "… is from another bank account or currency than run …"');
act($bea, '/payments/delete.php', ['payment' => $other]);
$mine = mk_payment($R1, $fx['bank'], [$D]);
$since = last_activity_id();
[$c, $b] = act($bea, '/payment-runs/add.php', ['payment_run' => $run, 'payment' => $mine]);
ok($c === 200 && (int) one('SELECT payment_run_id FROM payments WHERE id = :p', ['p' => $mine]) === $run && (string) one('SELECT total FROM payment_runs WHERE id = :r', ['r' => $run]) === '650.00' && count(activity('payment_run.add', $since)) === 1, 'payment_run_add: joined; the run total follows (650.00); logged');
[$c, $b] = act($bea, '/payment-runs/remove.php', ['payment_run' => $run, 'payment' => $mine]);
ok($c === 200 && one('SELECT payment_run_id FROM payments WHERE id = :p', ['p' => $mine]) === null && (string) one('SELECT total FROM payment_runs WHERE id = :r', ['r' => $run]) === '600.00', 'payment_run_remove: out again; 600.00');
[$c, $b] = act($bea, '/payment-runs/remove.php', ['payment_run' => $run, 'payment' => $mine]);
ok($c === 422 && str_contains(msg($b), 'is not in that run'), 'removing what is not in the run: 422');
act($bea, '/payments/delete.php', ['payment' => $mine]);
echo "4. Approve, with cheque numbers\n";
[$c, $b] = act($bea, '/payment-runs/approve.php', ['payment_run' => $run, 'first_cheque_number' => '2001']);
ok($c === 403, 'the Bookkeeper approving: 403');
[$c, $b] = act($carl, '/payment-runs/approve.php', ['payment_run' => $run]);
ok($c === 422 && str_contains(msg($b), 'is a cheque: give the first cheque number'), 'no first cheque number for cheque payments: 422 in words');
[$c, $b] = act($carl, '/payment-runs/approve.php', ['payment_run' => $run, 'first_cheque_number' => 'AB1']);
ok($c === 422 && isset(fields($b)['first_cheque_number']), 'a first cheque number that is not digits: 422 naming the field');
ok((string) one('SELECT status FROM payment_runs WHERE id = :r', ['r' => $run]) === 'draft' && (int) one("SELECT count(*) FROM payments WHERE payment_run_id = :r AND cheque_number IS NOT NULL", ['r' => $run]) === 0, 'a refused approval changes nothing');
$since = last_activity_id();
[$c, $b] = act($carl, '/payment-runs/approve.php', ['payment_run' => $run, 'first_cheque_number' => '2001']);
ok($c === 200 && ($b['location'] ?? '') === '/payment-runs/' . $run . '?notice=approved' && count($b['cheques'] ?? []) === 2, 'payment_run_approve with first cheque number 2001: 200, two cheques numbered');
$ps = q('SELECT cheque_number, method, status FROM payments WHERE payment_run_id = :r ORDER BY id', ['r' => $run]);
ok(array_column($ps, 'cheque_number') === ['2001', '2002', null] && array_unique(array_column($ps, 'status')) === ['approved'], 'the cheque payments are numbered 2001, 2002 in order (the ACH one has none); every payment approved');
ok((string) one('SELECT status FROM payment_runs WHERE id = :r', ['r' => $run]) === 'approved' && (int) one('SELECT approved_by FROM payment_runs WHERE id = :r', ['r' => $run]) === 28, 'the run is approved by 28');
$l = activity('payment_run.approve', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['amount'] === '600.00' && $a['payments'] === 3 && count($a['cheques']) === 2 && $a['cheques'][0]['cheque_number'] === '2001' && (int) $l['bank_account_id'] === $fx['bank'], 'payment_run.approve logs amount, payments and cheques[]');
[$c, $b] = act($bea, '/payment-runs/add.php', ['payment_run' => $run, 'payment' => $hold]);
ok($c === 422 && str_contains(msg($b), 'is approved; payments join a draft run'), 'adding to an approved run: 422 "… payments join a draft run"');
[$c, $b] = act($bea, '/payment-runs/remove.php', ['payment_run' => $run, 'payment' => (int) $ps[0] ?? 0 ?: (int) one('SELECT min(id) FROM payments WHERE payment_run_id = :r', ['r' => $run])]);
ok($c === 422, 'removing from an approved run: 422');
[$c, $b] = act($carl, '/payment-runs/approve.php', ['payment_run' => $run]);
ok($c === 422 && str_contains(msg($b), 'is already approved'), 'approving twice: 422');
echo "5. Record as paid\n";
$run2 = (int) act($bea, '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-03', 'bills' => [$D]])[1]['record_id'];
[$c, $b] = act($bea, '/payment-runs/record.php', ['payment_run' => $run2]);
ok($c === 422 && str_contains(msg($b), 'must be approved before it is recorded'), 'recording a draft run: 422');
[$c, $b] = act($vera, '/payment-runs/record.php', ['payment_run' => $run]);
ok($c === 403, 'the Viewer recording: 403');
$since = last_activity_id();
[$c, $b] = act($bea, '/payment-runs/record.php', ['payment_run' => $run, 'pay_date' => '2026-07-04']);
ok($c === 200 && ($b['location'] ?? '') === '/payment-runs/' . $run . '?notice=recorded' && ($b['payments'] ?? 0) === 3, 'payment_run_record: 200, three payments recorded');
$r = run_row($run);
ok($r['status'] === 'recorded' && $r['pay_date'] === '2026-07-04' && (int) $r['recorded_by'] === 27, 'the run is recorded by 27 on 4 Jul');
$ps = q('SELECT * FROM payments WHERE payment_run_id = :r ORDER BY id', ['r' => $run]);
ok(array_unique(array_column($ps, 'status')) === ['recorded'] && array_unique(array_column($ps, 'payment_date')) === ['2026-07-04'] && count(array_filter(array_column($ps, 'journal_entry_id'))) === 3, 'every payment recorded on the pay date, each posted');
ok(bill_row($A)['status'] === 'paid' && bill_row($B)['status'] === 'paid' && bill_row($C)['status'] === 'paid' && bill_row($D)['status'] === 'approved', 'the bills A, B and C are paid (D is not in the run)');
$tot = q("SELECT l.debit, l.credit, a.code FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e", ['e' => $ps[0]['journal_entry_id']]);
ok(count($tot) === 2, 'each payment posts DR AP / CR the bank (two lines)');
$l = activity('payment_run.record', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['amount'] === '600.00' && $a['payments'] === 3 && $a['pay_date'] === '2026-07-04' && (int) $l['bank_account_id'] === $fx['bank'] && count(activity('payment.record', $since)) === 0, 'payment_run.record logs amount, payments, pay_date');
echo "6. The CSV\n";
$since = last_activity_id();
$r = req('GET', '/payment-runs/' . $run . '?format=csv', ['jar' => $carl]);
$rows = array_map('str_getcsv', array_filter(explode("\n", $r['body'])));
ok($r['code'] === 200 && str_contains($r['headers'], 'text/csv') && str_contains($r['headers'], $run_number = run_row($run)['number'] . '.csv'), 'the CSV is a download named for the run');
ok(count($rows) === 4 && $rows[0] === ['payment', 'vendor', 'remit_address', 'amount', 'currency', 'method', 'cheque_number', 'pay_date', 'reference', 'bills'], 'a header and one row per payment');
$byVendor = array_column(array_slice($rows, 1), null, 1);
ok($byVendor['SMOKE Run Vendor One'][3] === '100.00' && $byVendor['SMOKE Run Vendor One'][6] === '2001' && $byVendor['SMOKE Run Vendor One'][9] === 'A-1' && $byVendor['SMOKE Run Vendor Two'][6] === '2002' && $byVendor['SMOKE Run Vendor Two'][9] === 'B-1' && $byVendor['SMOKE Run Vendor Three'][5] === 'ach' && $byVendor['SMOKE Run Vendor Three'][6] === '' && $byVendor['SMOKE Run Vendor Three'][9] === 'C-1', 'vendor, amount, cheque number and the bills\' references are in the rows');
ok(count(activity('export.download', $since)) === 1 && ((int) activity('export.download', $since)[0]['bank_account_id']) === $fx['bank'], 'the download is logged as export.download');
ok(req('GET', '/payment-runs/' . $run . '?format=csv', ['jar' => $bea])['code'] === 403, 'the Bookkeeper has no export right: 403');
echo "7. Void: partly recorded\n";
$X = ready_bill($R1, [['X bill', '1', '10.00']], ['vendor_ref' => 'X-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-20']);
$Y = ready_bill($R2, [['Y bill', '1', '20.00']], ['vendor_ref' => 'Y-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-20']);
$Z = ready_bill($R3, [['Z bill', '1', '30.00']], ['vendor_ref' => 'Z-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-20']);
$run3 = (int) act($bea, '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-21', 'bills' => [$X, $Y, $Z]])[1]['record_id'];
$p3 = q('SELECT id FROM payments WHERE payment_run_id = :r ORDER BY id', ['r' => $run3]);
act($carl, '/payment-runs/approve.php', ['payment_run' => $run3, 'first_cheque_number' => '3001']);
[$c, $b] = act($bea, '/payments/record.php', ['payment' => (int) $p3[0]['id']]);
ok($c === 200 && (string) one('SELECT status FROM payments WHERE id = :p', ['p' => $p3[0]['id']]) === 'recorded', 'one payment of the approved run is recorded on its own');
[$c, $b] = act($bea, '/payment-runs/void.php', ['payment_run' => $run3, 'reason' => 'SMOKE x']);
ok($c === 403, 'a Bookkeeper voiding a run: 403');
[$c, $b] = act($carl, '/payment-runs/void.php', ['payment_run' => $run3, 'reason' => '']);
ok($c === 422 && str_contains(msg($b), 'Voiding a payment run needs a reason'), 'no reason: 422');
$since = last_activity_id();
[$c, $b] = act($carl, '/payment-runs/void.php', ['payment_run' => $run3, 'reason' => 'SMOKE the other two were wrong']);
ok($c === 200 && ($b['partly_recorded'] ?? false) === true, 'payment_run_void: 200, partly recorded');
$ps = q('SELECT status FROM payments WHERE payment_run_id = :r ORDER BY id', ['r' => $run3]);
ok(array_column($ps, 'status') === ['recorded', 'void', 'void'], 'the unrecorded payments are voided; the recorded one stays');
ok((string) one('SELECT status FROM payment_runs WHERE id = :r', ['r' => $run3]) === 'recorded' && (string) one('SELECT total FROM payment_runs WHERE id = :r', ['r' => $run3]) === '10.00', 'the run reads recorded, with a total of what stays (10.00)');
ok(bill_row($Y)['status'] === 'approved' && bill_row($Z)['status'] === 'approved' && bill_row($X)['status'] === 'paid', 'Y and Z are owed again; X stays paid');
$l = activity('payment_run.void', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['voided_payments'] === 2 && $a['kept_recorded'] === 1 && str_contains($a['reason'], 'other two'), 'payment_run.void logs the reason, voided_payments and kept_recorded');
$body = page($carl, '/payment-runs/' . $run3)['body'];
ok(str_contains($body, 'id="payment-run-head-partly"') && str_contains($body, 'partly recorded'), 'the run page says "partly recorded"');
[$c, $d] = screen($carl, '/payment-runs/' . $run3);
ok(($d['payment_run']['partly_recorded'] ?? false) === true && count($d['payment_run']['payments'] ?? []) === 3, 'JSON: partly_recorded true');
[$c, $b] = act($carl, '/payment-runs/void.php', ['payment_run' => $run, 'reason' => 'SMOKE all recorded']);
ok($c === 422 && str_contains(msg($b), 'is recorded; void a payment to undo it'), 'a run whose payments are all recorded cannot be voided as a run: 422 "… void a payment to undo it"');
[$c, $b] = act($carl, '/payment-runs/void.php', ['payment_run' => $run2, 'reason' => 'SMOKE draft run']);
ok($c === 200 && (string) one('SELECT status FROM payment_runs WHERE id = :r', ['r' => $run2]) === 'void' && (string) one("SELECT status FROM payments WHERE payment_run_id = :r", ['r' => $run2]) === 'void' && bill_row($D)['status'] === 'approved', 'a draft run with nothing recorded is voided whole; its bill is free');
[$c, $b] = act($carl, '/payment-runs/void.php', ['payment_run' => $run2, 'reason' => 'again']);
ok($c === 422 && str_contains(msg($b), 'is void and cannot be changed'), 'a void run cannot be voided again');
echo "8. The pages\n";
$body = page($bea, '/payment-runs/')['body'];
ok(str_contains($body, 'id="payment-run-card-' . $run . '"') && str_contains($body, 'id="payment-runs-tab-recorded"'), 'the list: a card for the run; tabs');
$d = screen($bea, '/payment-runs/?status=recorded')[1];
ok(array_unique(array_column($d['payment_runs'] ?? [], 'status')) === ['recorded'], 'status filters');
$body = page($carl, '/payment-runs/' . $run)['body'];
$firstPay = (int) one('SELECT min(id) FROM payments WHERE payment_run_id = :r', ['r' => $run]);
ok(str_contains($body, 'id="payment-run-csv-link"') && str_contains($body, 'id="run-payment-' . $firstPay . '"'), 'the Controller\'s run page carries the CSV link and the payments');
$run4 = (int) act($bea, '/payment-runs/save.php', ['bank_account' => $fx['bank'], 'pay_date' => '2026-07-22', 'bills' => [$Y]])[1]['record_id'];
$body = page($carl, '/payment-runs/' . $run4)['body'];
ok(str_contains($body, 'id="payment-run-approve-btn"') && str_contains($body, 'id="payment-run-first-cheque"'), 'a draft run with a cheque payment asks the Controller for the first cheque number');
finish();
